import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")
    cdc_events["seq"] = cdc_events["seq"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence per seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort events by seq for processing in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Build state as dict for easier manipulation
    # state: order_id -> {status, amount, last_seq}
    state = {}
    for _, row in target_state.iterrows():
        state[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders had their last applied event as DELETE
    # Maps order_id -> seq of the delete event
    tombstones_map = {}

    # Track which orders have been touched in this batch
    touched_orders = set()

    # Step 4: Apply events in seq order
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        touched_orders.add(order_id)

        # Apply replay guard: skip if order exists and seq <= last_seq
        if order_id in state:
            if seq <= state[order_id]["last_seq"]:
                continue

        # Apply the operation
        if op in ("I", "U"):
            if order_id in state:
                # Update existing row
                if pd.isna(amount):
                    # U with NULL amount: keep existing amount
                    state[order_id]["status"] = status
                    # amount stays unchanged
                else:
                    # Set new amount
                    state[order_id]["amount"] = amount
                    state[order_id]["status"] = status
            else:
                # Create new row (I for new, or U for missing)
                state[order_id] = {
                    "status": status,
                    "amount": amount
                }
            state[order_id]["last_seq"] = seq
            # Remove from tombstones if was deleted before
            if order_id in tombstones_map:
                del tombstones_map[order_id]

        elif op == "D":
            if order_id in state:
                del state[order_id]
            # Track this delete as the last event for this order
            tombstones_map[order_id] = seq

    # Step 5: Build new_state output
    new_state_rows = []
    for order_id, data in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": data["status"],
            "amount": data["amount"],
            "last_seq": data["last_seq"]
        })

    if new_state_rows:
        new_state_df = pd.DataFrame(new_state_rows)
    else:
        new_state_df = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    # Step 6: Build tombstones output
    # Only include tombstones for orders that were touched
    tombstones_rows = []
    for order_id, deleted_seq in tombstones_map.items():
        if order_id in touched_orders:
            tombstones_rows.append({
                "order_id": order_id,
                "deleted_seq": deleted_seq
            })

    if tombstones_rows:
        tombstones_df = pd.DataFrame(tombstones_rows)
    else:
        tombstones_df = pd.DataFrame(columns=["order_id", "deleted_seq"])

    # Ensure correct dtypes
    if not new_state_df.empty:
        new_state_df["order_id"] = new_state_df["order_id"].astype("int64")
        new_state_df["status"] = new_state_df["status"].astype("object")
        new_state_df["amount"] = new_state_df["amount"].astype("float64")
        new_state_df["last_seq"] = new_state_df["last_seq"].astype("int64")

    if not tombstones_df.empty:
        tombstones_df["order_id"] = tombstones_df["order_id"].astype("int64")
        tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype("int64")

    return {
        "new_state": new_state_df,
        "tombstones": tombstones_df
    }
